{
    "test_cases": [
        {
            "group": "removeRecord - null record",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "record",
                            "value": "null"
                        }
                    ],
                    "expected": "NullPointerException",
                    "description": "Calling removeRecord with a null argument should throw NullPointerException when the method attempts to invoke r.getName()."
                }
            ]
        },
        {
            "group": "removeRecord - record with null name",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "record",
                            "value": "recordWithNullName"
                        }
                    ],
                    "expected": "NullPointerException",
                    "description": "If the supplied Record returns null for getName(), findRRset is invoked with a null Name, which should result in a NullPointerException."
                }
            ]
        },
        {
            "group": "removeRecord - record not present in RRset (size > 1)",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "record",
                            "value": "recordNotInRRsetMultiple"
                        }
                    ],
                    "expected": "NoSuchElementException",
                    "description": "The Zone contains an RRset for the Record's name/type with more than one entry, but the specific Record is not part of that RRset. Calling deleteRR on the RRset should throw NoSuchElementException."
                }
            ]
        },
        {
            "group": "removeRecord - record not present in RRset (size == 1)",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "record",
                            "value": "recordNotInRRsetSingle"
                        }
                    ],
                    "expected": "NoSuchElementException",
                    "description": "The Zone contains an RRset of size 1 for the Record's name/type, but the sole entry differs from the supplied Record. The method will fall into the else branch and invoke deleteRR, which should throw NoSuchElementException because the Record is absent."
                }
            ]
        }
    ]
}
